import re
from mem0 import Memory

m = Memory()
BLOCK = [r"\b\d{4}\s?\d{4}\s?\d{4}\b",        # Aadhaar-like 12 digits
         r"\b[A-Z]{5}\d{4}[A-Z]\b",           # PAN
         r"\b\d{6}\b.*\bOTP\b|\bOTP\b.*\b\d{6}\b"]
ALLOW = {"language", "channel", "goal", "address"}

def save(user_id: str, category: str, text: str):
    if category not in ALLOW or any(re.search(p, text, re.I) for p in BLOCK):
        return None                                        # never written anywhere
    return m.add(text, user_id=user_id, metadata={"category": category},
                 infer=False)

def erase(user_id: str, audit):
    m.delete_all(user_id=user_id)                          # memories and their vectors
    drop_summaries(user_id); drop_cache(user_id)           # every other copy
    audit.write({"event": "erasure", "user": user_id})     # proof, not the data
